#!/usr/bin/env node
/**
 * Books one verified tip receipt. The booking is first kept in the one log, the semantic record
 * journal (kind `tips.payment-service-record`, category `tip-booking.transactions`), with the
 * verified receipt and its balanced Beancount directive derived via `compute-tip-transaction.mjs`.
 * The dated sidecar under this section's own `data/logs/ledgers/` is then rendered whole from every
 * booking of that date the journal holds, headed exactly like the Group's other generated sidecars
 * ("Generated by <script>. Do not hand-edit."), so the books session can `include` or copy it into
 * the main ledger's own directory. The sidecar is a projection: removing it loses nothing, and this
 * operation never writes to the main ledger itself.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { parseArgs } from "node:util";
import { createSemanticRecordJournal } from "@red-cup-engineering/semantic-record-journal-service";
import { packageRoot } from "../src/tips.mjs";
import { computeTipTransaction } from "./compute-tip-transaction.mjs";

const HEADER = "; Generated by scripts/book-tip.mjs (@red-cup-engineering/tips-services-section). Do not hand-edit.\n";
const OPEN_LINE = /^\d{4}-\d{2}-\d{2} open (\S+)$/mu;
const POSTING_LINE = /^ {2}([A-Z][\w-]*(?::[\w-]+)+) {2}/u;
export const TIP_BOOKING_OBJECT_KIND = "tips.payment-service-record";
export const TIP_BOOKING_CATEGORY = "tip-booking.transactions";

function existingOpenAccounts(text) {
  const accounts = new Set();
  for (const line of text.split("\n")) {
    const match = OPEN_LINE.exec(line);
    if (match) accounts.add(match[1]);
  }
  return [...accounts];
}

/** The accounts a directive posts to, in order. */
function postedAccounts(directive) {
  return [...new Set(directive.split("\n").map((line) => POSTING_LINE.exec(line)?.[1]).filter(Boolean))];
}

/**
 * The sidecar for one date as a projection of the journal: the header, then each booking of that
 * date the journal holds (once per receipt, in the order booked), each preceded by `open`
 * directives for the accounts it posts to that neither an earlier booking nor a `knownOpen` file
 * opened.
 * @returns {{text: string, opened: Map<string, object[]>}} The sidecar text and, per receipt, the opens rendered before it.
 */
export function renderTipSidecar(bookings, date, { knownOpenText = "" } = {}) {
  const open = new Set(existingOpenAccounts(knownOpenText));
  const seen = new Set();
  const blocks = [HEADER];
  const opened = new Map();
  for (const booking of bookings) {
    if (typeof booking?.directive !== "string" || booking.directive.slice(0, 10) !== date || seen.has(booking.receiptId)) continue;
    seen.add(booking.receiptId);
    const opens = postedAccounts(booking.directive).filter((account) => !open.has(account))
      .map((account) => ({ account, date, directive: `${date} open ${account}` }));
    for (const entry of opens) { open.add(entry.account); blocks.push(entry.directive); }
    blocks.push(booking.directive);
    opened.set(booking.receiptId, opens);
  }
  return { text: `${blocks.join("\n\n")}\n`, opened };
}

/**
 * Books `receipt`: keeps the booking in the journal, then renders the dated sidecar at
 * `sidecarPath` (default: this section's own `data/logs/ledgers/<receipt date>-tip-transactions.beancount`)
 * from every booking of that date the journal holds.
 * @param {{rail: string, provider: string, receiver: string, amount: string, currency: string, feeAmount?: string, receiptId: string, verifiedAt: string}} receipt A verified tip receipt (verify-tip-receipt.mjs's `{verified: true, receipt}` shape).
 * @param {{sidecarPath?: string, journalRoot?: string, journal?: {record: Function, query: Function}, now?: Date, knownOpenPaths?: string[]}} [options] `knownOpenPaths` names other Beancount files (e.g. the main ledger) to scan for accounts already open there, so this sidecar never re-`open`s one the books already carry.
 * @returns {{booked: true, path: string, directive: string, accountsToOpen: object[]}} What was booked, and the opens rendered before it.
 * @throws {TypeError} When `receipt.amount` is not a positive decimal string (propagated from `computeTipTransaction`).
 */
export function bookTip(receipt, options = {}) {
  const date = receipt.verifiedAt.slice(0, 10);
  const root = packageRoot();
  const sidecarPath = options.sidecarPath ?? join(root, "data/logs/ledgers", `${date}-tip-transactions.beancount`);
  const knownOpenText = (options.knownOpenPaths ?? []).filter(existsSync).map((path) => readFileSync(path, "utf8")).join("\n");
  const { directive } = computeTipTransaction({ receipt, openAccounts: [] });

  const journal = options.journal ?? createSemanticRecordJournal({ root: options.journalRoot ?? root, objectKind: TIP_BOOKING_OBJECT_KIND });
  journal.record({
    category: TIP_BOOKING_CATEGORY,
    recordedAt: (options.now ?? new Date()).toISOString(),
    record: { receiptId: receipt.receiptId, rail: receipt.rail, provider: receipt.provider, amount: receipt.amount, currency: receipt.currency, sidecarPath, directive, receipt },
    charge: { support: true, refutation: false },
  });

  const bookings = journal.query({ category: TIP_BOOKING_CATEGORY }).map((row) => row.record);
  const { text, opened } = renderTipSidecar(bookings, date, { knownOpenText });
  mkdirSync(dirname(sidecarPath), { recursive: true });
  writeFileSync(sidecarPath, text);
  return { booked: true, path: sidecarPath, directive, accountsToOpen: opened.get(receipt.receiptId) ?? [] };
}

if (import.meta.main) {
  const { values } = parseArgs({ options: { out: { type: "string" }, "journal-root": { type: "string" }, "known-open": { type: "string", multiple: true } } });
  let text = "";
  for await (const chunk of process.stdin) text += chunk;
  const receipt = JSON.parse(text);
  const result = bookTip(receipt, { sidecarPath: values.out, journalRoot: values["journal-root"], knownOpenPaths: values["known-open"] });
  process.stdout.write(`${JSON.stringify(result)}\n`);
}
